// ListNode is supplied by the platform.
class Solution {
    public ListNode reverseList(ListNode head) {
        ListNode prev = null;
        ListNode curr = head;
        while (curr != null) {
            ListNode nextNode = curr.next; // Save the untouched suffix.
            curr.next = prev;             // Reverse this link.
            prev = curr;
            curr = nextNode;
        }
        return prev;
    }
}

