// Nodes have val and next fields.
function reverseList(head) {
    let prev = null;
    let curr = head;
    while (curr !== null) {
        const nextNode = curr.next; // Save the untouched suffix.
        curr.next = prev;           // Reverse this link.
        prev = curr;
        curr = nextNode;
    }
    return prev;
}
